import React from "react";
import Footer from "./Footer";
import { useNavigate } from "react-router-dom";
import { useEffect, useState } from "react";
import { getDatabase, ref, get, set } from "firebase/database";
import { database } from "./firebase"; 


const Acerca = () => {
 
    const navigate = useNavigate();
    const [visitas, setVisitas] = useState(0);
    
    const back = () =>{
    navigate('/')
 } 
    useEffect(() => {
        const db = getDatabase();
        const visitasRef = ref(db, "contadorVisitas");

        get(visitasRef).then((snapshot) => {
            if (snapshot.exists()) {
                const nuevasVisitas = snapshot.val() + 1;
                setVisitas(nuevasVisitas);
                set(visitasRef, nuevasVisitas); // Actualiza el contador en Firebase
            } else {
                setVisitas(1);
                set(visitasRef, 1); // Si no existe, lo inicializa en 1
            }
        });
    }, []);

    return (
        <div className="acerca-container">
            <h2 className="contactos">Nosotros</h2>
            <div className="acerca-seccion">
                <h3>HumaBrc - Cerámica de Calidad</h3>
                <p>
                    Ale crea piezas de cerámica artesanal de alta calidad, diseñadas para ser tanto estéticas como funcionales. Sus productos utilitarios están libres de componentes tóxicos, garantizando seguridad y durabilidad en el uso diario.
                </p>
            </div>
            <div className="acerca-seccion">
                <h3>Nuestros Sahumerios, Esferas y Esencias</h3>
                <p>
                    Ofrecemos una variedad de sahumerios, esferas energéticas, esencias y otros productos ideales para la armonización de espacios y el bienestar personal. Cada artículo está seleccionado con cuidado para brindar experiencias sensoriales únicas.
                </p>
            </div>
            <p className="contador-visitas">Esta página ha sido visitada {visitas} veces.</p>
      <button className="back" onClick={back}>VOLVER</button>

       <Footer/>
        </div>
    );
};

export default Acerca;
