import React from 'react';
import whats from './logos/whats.png';
import insta from './logos/insta.png';
import contact from './logos/contact.png';

const Footer = ({ setShowLogin }) => {
    return (
        <div className='imageFooter'>
            {/* Enlace a WhatsApp */}
            <a className='footerText' href="https://wa.me/+5492944895986" target="_blank" rel="noopener noreferrer">
                <img
                    className='imageFooter2'
                    alt='whatsapp'
                    src={whats}
                    title="WhatsApp"
                /> Contactame por whatsapp
            </a>

            {/* Enlace a Instagram */}
            <a className='footerText' href="https://www.instagram.com/huma.brc" target="_blank" rel="noopener noreferrer">
                <img
                    className='imageFooter2'
                    alt='instagram'
                    src={insta}
                    title="Instagram"
                />Seguime en Instagram
            </a>

   
    
      
        </div>
    );
};

export default Footer;
