import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import platos from './fotos/platos2.jpg';
import mate from './fotos/mate.jpg';
import mates from './fotos/matess.jpg';
import vario from './fotos/varios.jpg';
import varios from './fotos/varios2.jpg';
import porta from './fotos/portas.jpg';
import whats from './logos/whats.png';
import taza from './fotos/taza.jpg'
import taza2 from './fotos/taza2.jpg'
import taza3 from './fotos/taza3.jpg'

const GaleriaLocal = () => {
    // Definir un array con las imágenes locales
    const imagenesLocales = [
        { nombre: 'Platos', src: platos },
        { nombre: 'Mate', src: mate },
        { nombre: 'Mates', src: mates },
        { nombre: 'Varios', src: vario },
        { nombre: 'Varios y mas', src: varios },
        { nombre: 'Porta sahumerios ', src: porta },
        { nombre: 'taza con calco', src: taza },
        { nombre: ' Otra taza ', src: taza2 },
        { nombre: ' Otra taza ', src: taza3 },
    ];

    const [productoSeleccionado, setProductoSeleccionado] = useState(null);

    const getWhatsAppLink = (producto) => {
        const phone = "542944895986"; // Número de WhatsApp del vendedor (cámbialo)
        const message = `Hola, estoy interesado en el producto: ${producto.nombre}`;
        return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
    };

    return (
        <div className="galeria-container">
            <div className="galeria-grid">
                {imagenesLocales.map((imagen, index) => (
                    <motion.div
                        key={index}
                        className="galeria-item"
                        whileHover={{ scale: 1.05 }} // Animación al pasar el cursor por encima
                        whileTap={{ scale: 0.95 }} // Animación al hacer clic
                        transition={{ type: 'spring', stiffness: 300, damping: 20 }} // Parámetros de la animación
                        onClick={() => setProductoSeleccionado(imagen)} // Establecer la imagen seleccionada al hacer clic
                    >
                        <img className="galeria-imagen" src={imagen.src} alt={imagen.nombre} />
                        <div className="galeria-overlay">
                            <p>{imagen.nombre}</p>
                        </div>
                    </motion.div>
                ))}
            </div>

            <AnimatePresence>
                {productoSeleccionado && (
                    <motion.div
                        className="modal-overlay"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={() => setProductoSeleccionado(null)} // Cerrar al hacer clic fuera
                    >
                        <motion.div
                            className="modal-content"
                            initial={{ scale: 0.8 }}
                            animate={{ scale: 1 }}
                            exit={{ scale: 0.8 }}
                            onClick={(e) => e.stopPropagation()} // No cerrar al hacer clic dentro del modal
                        >
                            <img src={productoSeleccionado.src} alt={productoSeleccionado.nombre} />
                            <p>{productoSeleccionado.descripcion || "Sin descripción disponible"}</p>

                            <div className="modal-buttons">
                                <a
                                    href={getWhatsAppLink(productoSeleccionado)}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="whatsapp-button"
                                >
                                    <img className="iconoW" src={whats} alt="WhatsApp" />
                                </a>
                                <button onClick={() => setProductoSeleccionado(null)}>Cerrar</button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default GaleriaLocal;
