import { useState } from "react";
import GuardarProducto from "./GuardarProducto";
import MostrarProductos from "./MostrarProductos";
import Footer from "./Footer";
import { motion } from "framer-motion";
import Navbar from "./Navbar";

function Home() {
    const [usuario, setUsuario] = useState("");
    const [contrasena, setContrasena] = useState("");
    const [isAle, setIsAle] = useState(false);
    const [error, setError] = useState("");
    const [showLogin, setShowLogin] = useState(false);

    const handleLogin = () => {
        if (usuario === "Ale" && contrasena === "ñandu1234") {
            setIsAle(true);
            setError("");
            setShowLogin(false);
        } else {
            setIsAle(false);
            setError("Usuario o contraseña incorrectos");
        }
    };

    return (
        <div className="displayFlex fondo">
           
            {/* Botón de login arriba a la izquierda */}
            {!isAle && (
                <motion.button
                    className="login-button"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                    onClick={() => setShowLogin(!showLogin)}
                >
                    Iniciar sesión
                </motion.button>
            )}

            {/* Formulario de login con botón de cerrar */}
            {showLogin && !isAle && (
                <motion.div
                    className="login-modal"
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5 }}
                >
                    {/* Botón para cerrar el modal */}
                    <button className="close-button" onClick={() => setShowLogin(false)}>✖</button>

                    <h3>Iniciar sesión</h3>
                   
                    <input
                        className="inputLog"
                        type="text"
                        placeholder="Nombre de usuario"
                        value={usuario}
                        onChange={(e) => setUsuario(e.target.value)}
                    />
                    <input
                        className="inputLog"
                        type="password"
                        placeholder="Contraseña"
                        value={contrasena}
                        onChange={(e) => setContrasena(e.target.value)}
                    />
                    <motion.button
                        className="login"
                        whileHover={{ scale: 1.1 }}
                        onClick={handleLogin}
                    >
                        Entrar
                    </motion.button>
                    {error && <p style={{ color: "red" }}>{error}</p>}
                </motion.div>
            )}

            {/* Si el usuario ya está logueado, muestra la interfaz de admin */}
            {isAle && (
                <div>
                    <h2>Bienvenido, {usuario}</h2>
                    <GuardarProducto />
                </div>
            )}

            {/* Contenido público */}
            <MostrarProductos />
            <Footer />
        </div>
    );
}

export default Home;

