import React from "react";
import Footer from "./Footer";
import { useNavigate } from "react-router-dom";
const Info = () =>{
  
  const navigate = useNavigate();  

   const back = () =>{
    navigate('/');
   }
   
   return(
<div>
    <h2 className="tituloGaleria">INFO</h2>
            <div className="acerca-seccion2">
    <p className="info4">Esta página fue creada para realizar pedidos on-line</p>
    <p className="info2">No esta hecha para realizar compras directamente</p>
                <p className="info3">Muchas Gracias</p>
            </div>

    <button className="back" onClick={back}>VOLVER</button>
<Footer/>
</div>



    )
}

export default Info;