import { useState, useEffect } from "react";
import { getDatabase, ref, set, get, update, remove } from "firebase/database";
import SubirImagen from "./SubirImagen";
import { database } from "./firebase";

const GuardarProducto = () => {
    const [productos, setProductos] = useState([]);
    const [productoSeleccionado, setProductoSeleccionado] = useState(null);
    const [nombre, setNombre] = useState("");
    const [nuevoNombre, setNuevoNombre] = useState(""); // Para permitir cambiar el nombre
    const [precio, setPrecio] = useState("");
    const [stock, setStock] = useState("");
    const [descripcion, setDescripcion] = useState("");
    const [categoria, setCategoria] = useState(""); // Nuevo campo de categoría
    const [imageUrl, setImageUrl] = useState("");

    useEffect(() => {
        const db = getDatabase();
        const productsRef = ref(db, "productos/");
        get(productsRef).then((snapshot) => {
            if (snapshot.exists()) {
                setProductos(Object.entries(snapshot.val()));
            }
        });
    }, []);

    const guardarEnFirebase = () => {
        if (!nombre || !precio || !stock || !imageUrl || !descripcion || !categoria) {
            alert("Completa todos los campos");
            return;
        }

        const db = getDatabase();
        const productRef = ref(db, `productos/${nombre}`);

        set(productRef, { nombre, precio, stock, descripcion, categoria, imageUrl })
            .then(() => {
                alert("Producto guardado");
                setProductos([...productos, [nombre, { nombre, precio, stock, descripcion, categoria, imageUrl }]]);
                limpiarCampos();
            })
            .catch((error) => alert("Error: " + error));
    };

    const seleccionarProducto = (id, producto) => {
        setProductoSeleccionado(id);
        setNombre(producto.nombre);
        setNuevoNombre(producto.nombre); // Para permitir cambiar el nombre
        setPrecio(producto.precio);
        setStock(producto.stock);
        setDescripcion(producto.descripcion);
        setCategoria(producto.categoria);
        setImageUrl(producto.imageUrl);
    };

    const actualizarProducto = async () => {
        if (!productoSeleccionado) return;

        const db = getDatabase();
        const oldRef = ref(db, `productos/${productoSeleccionado}`);
        const newRef = ref(db, `productos/${nuevoNombre}`);

        if (productoSeleccionado !== nuevoNombre) {
            // Si el nombre cambió, eliminamos el antiguo y creamos uno nuevo
            await remove(oldRef);
        }

        update(newRef, { nombre: nuevoNombre, precio, stock, descripcion, categoria, imageUrl })
            .then(() => {
                alert("Producto actualizado");
                setProductos((prev) => prev.map(([id, prod]) => id === productoSeleccionado ? [nuevoNombre, { nombre: nuevoNombre, precio, stock, descripcion, categoria, imageUrl }] : [id, prod]));
                limpiarCampos();
            })
            .catch((error) => alert("Error: " + error));
    };

    const eliminarProducto = async (id) => {
        try {
            const db = getDatabase();
            const productRef = ref(db, `productos/${id}`);

            await remove(productRef);

            alert("Producto eliminado con éxito");

            setProductos((prev) => prev.filter(([key]) => key !== id));
        } catch (error) {
            console.error("Error al eliminar el producto:", error);
            alert("Error al eliminar el producto");
        }
    };

    const limpiarCampos = () => {
        setProductoSeleccionado(null);
        setNombre("");
        setNuevoNombre("");
        setPrecio("");
        setStock("");
        setDescripcion("");
        setCategoria("");
        setImageUrl("");
    };

    return (
        <div className="ingresarProd">
            <h3>{productoSeleccionado ? "Editar Producto" : "Agregar Producto"}</h3>
            <input
                className="inputProd"
                type="text"
                placeholder="Nombre"
                value={nuevoNombre}
                onChange={(e) => setNuevoNombre(e.target.value)}
            />
            <input
                className="inputProd precio"
                type="number"
                placeholder="Precio"
                value={precio}
                onChange={(e) => setPrecio(e.target.value)}
            />
            <input
                className="inputProd stock"
                type="number"
                placeholder="Stock"
                value={stock}
                onChange={(e) => setStock(e.target.value)}
            />
            <input
                className="inputProd"
                type="text"
                placeholder="Categoría"
                value={categoria}
                onChange={(e) => setCategoria(e.target.value)}
            />
            <textarea
                className="inputProd"
                placeholder="Descripción"
                value={descripcion}
                onChange={(e) => setDescripcion(e.target.value)}
                rows="3"
            />
            <SubirImagen onUpload={setImageUrl} />
            {productoSeleccionado ? (
                <button className="login" onClick={actualizarProducto}>Actualizar Producto</button>
            ) : (
                <button className="login" onClick={guardarEnFirebase}>Guardar Producto</button>
            )}

            <h3>Productos Guardados</h3>
            <ul>
                {productos.map(([id, producto]) => (
                    <li key={id}>
                        {producto.nombre} - ${producto.precio} - {producto.categoria}
                        <button className="login" onClick={() => seleccionarProducto(id, producto)}>Editar</button>
                        <button className="login" onClick={() => eliminarProducto(id)}>Eliminar</button>
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default GuardarProducto;
