import { useEffect, useState } from "react";
import { getDatabase, ref, get } from "firebase/database";
import { motion, AnimatePresence } from "framer-motion";
import { useNavigate } from "react-router-dom";
import whats from './logos/whats.png'
import GaleriaLocal from "./GaleriaLocal";


const Galeria = () => {
    const [productos, setProductos] = useState([]);
    const [productoSeleccionado, setProductoSeleccionado] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        const db = getDatabase();
        const productsRef = ref(db, "productos/");

        get(productsRef)
            .then((snapshot) => {
                if (snapshot.exists()) {
                    setProductos(Object.values(snapshot.val()));
                } else {
                    console.log("No hay productos en la base de datos.");
                }
            })
            .catch((error) => {
                console.error("Error al obtener los productos:", error);
            });
    }, []);

    const back = () => {
        navigate("/");
    };

    // Generar enlace de WhatsApp con mensaje personalizado
    const getWhatsAppLink = (producto) => {
        const phone = "542944895986"; // Número de WhatsApp del vendedor (cámbialo)
        const message = `Hola, estoy interesado en el producto: ${producto.nombre}`;
        return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
    };

    return (
        <div className="galeria-container">
            <h2 className="tituloGaleria">Galería de Productos</h2>

            <div className="galeria-grid">
                {productos.length > 0 ? (
                    productos.map((producto, index) => (
                        <motion.div
                            key={index}
                            className="galeria-item"
                            whileHover={{ scale: 1.05 }}
                            whileTap={{ scale: 0.95 }}
                            onClick={() => setProductoSeleccionado(producto)}
                        >
                            {producto.imageUrl ? (
                                <>
                                    <img className="galeria-imagen" src={producto.imageUrl} alt={producto.nombre} />
                                    <div className="galeria-overlay">
                                        <p>{producto.nombre}</p>
                                    </div>
                                </>
                            ) : (
                                <p>No hay imagen disponible</p>
                            )}
                        </motion.div>
                    ))
                ) : (
                    <p>No se encontraron productos.</p>
                )}
            </div>

            {/* Botón de volver */}
           

            {/* Modal de imagen ampliada */}
            <AnimatePresence>
                {productoSeleccionado && (
                    <motion.div
                        className="modal-overlay"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={() => setProductoSeleccionado(null)}
                    >
                        <motion.div
                            className="modal-content"
                            initial={{ scale: 0.8 }}
                            animate={{ scale: 1 }}
                            exit={{ scale: 0.8 }}
                            onClick={(e) => e.stopPropagation()}
                        >
                            <img src={productoSeleccionado.imageUrl} alt={productoSeleccionado.nombre} />
                            <p>{productoSeleccionado.descripcion || "Sin descripción disponible"}</p>

                            <div className="modal-buttons">
                                <a
                                    href={getWhatsAppLink(productoSeleccionado)}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="whatsapp-button"
                                >
                                    <img className="iconoW" src={whats} />
                                </a>
                                <button onClick={() => setProductoSeleccionado(null)}>Cerrar</button>
                              
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
       <GaleriaLocal/>
            <button className="back" onClick={back}>VOLVER</button>
        </div>
    );
};

export default Galeria;
